<?php
declare(strict_types=1);require_once __DIR__.'/auth_check.php';require_once __DIR__.'/bootstrap.php';
$pdo=app_database();function pfh(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
if(!isset($_SESSION['product_sheet_csrf']))$_SESSION['product_sheet_csrf']=bin2hex(random_bytes(24));
$products=$pdo->query('SELECT id_produit,designation FROM produit ORDER BY designation')->fetchAll(PDO::FETCH_ASSOC);$productId=(int)($_GET['id']??$_POST['produit_id']??0);
if($_SERVER['REQUEST_METHOD']==='POST'&&hash_equals($_SESSION['product_sheet_csrf'],(string)($_POST['csrf_token']??''))&&$productId>0){$pdo->beginTransaction();try{$sql='INSERT INTO produit_fiche(produit_id,categorie,marque,reference_fabricant,description_courte,description_longue,garantie,pays_origine,delai_livraison) VALUES(:id,:categorie,:marque,:reference,:courte,:longue,:garantie,:origine,:delai) ON DUPLICATE KEY UPDATE categorie=VALUES(categorie),marque=VALUES(marque),reference_fabricant=VALUES(reference_fabricant),description_courte=VALUES(description_courte),description_longue=VALUES(description_longue),garantie=VALUES(garantie),pays_origine=VALUES(pays_origine),delai_livraison=VALUES(delai_livraison)';$pdo->prepare($sql)->execute(['id'=>$productId,'categorie'=>trim((string)$_POST['categorie'])?:null,'marque'=>trim((string)$_POST['marque'])?:null,'reference'=>trim((string)$_POST['reference_fabricant'])?:null,'courte'=>trim((string)$_POST['description_courte'])?:null,'longue'=>trim((string)$_POST['description_longue'])?:null,'garantie'=>trim((string)$_POST['garantie'])?:null,'origine'=>trim((string)$_POST['pays_origine'])?:null,'delai'=>trim((string)$_POST['delai_livraison'])?:null]);$pdo->prepare('DELETE FROM produit_specification WHERE produit_id=?')->execute([$productId]);$spec=$pdo->prepare('INSERT INTO produit_specification(produit_id,libelle,valeur,position) VALUES(?,?,?,?)');foreach((array)($_POST['spec_label']??[])as$i=>$label){$label=trim((string)$label);$value=trim((string)(($_POST['spec_value']??[])[$i]??''));if($label!==''&&$value!=='')$spec->execute([$productId,$label,$value,$i]);}$pdo->commit();header('Location: fiches_produits.php?id='.$productId.'&saved=1');exit;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error='La fiche n’a pas pu être enregistrée.';}}
$sheet=[];$specs=[];$selected=null;if($productId){$s=$pdo->prepare('SELECT p.*,f.* FROM produit p LEFT JOIN produit_fiche f ON f.produit_id=p.id_produit WHERE p.id_produit=?');$s->execute([$productId]);$selected=$s->fetch(PDO::FETCH_ASSOC);$s=$pdo->prepare('SELECT * FROM produit_specification WHERE produit_id=? ORDER BY position,id');$s->execute([$productId]);$specs=$s->fetchAll(PDO::FETCH_ASSOC);}if(!$specs)$specs=[['libelle'=>'','valeur'=>'']];
?>
<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Fiches produits | FIDEST</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.0/css/all.min.css" rel="stylesheet"><link rel="stylesheet" href="css/style.css"><link rel="stylesheet" href="css/modules.css"><link rel="stylesheet" href="css/smart-select.css"><style>.sheet-card{padding:25px;background:#fff;border:1px solid var(--brand-border);border-radius:20px}.sheet-selector{margin-bottom:20px}.spec-row{display:grid;grid-template-columns:1fr 1.4fr 42px;gap:8px;margin-bottom:8px}.sheet-actions{display:flex;gap:10px;flex-wrap:wrap}@media(max-width:600px){.spec-row{grid-template-columns:1fr 1fr}.spec-row button{grid-column:1/-1}}</style></head><body class="module-page product-sheet-page"><?php include __DIR__.'/partials/navbar.php';?><main class="container"><div class="module-heading"><div class="module-heading__copy"><span class="module-heading__icon"><i class="fa-solid fa-clipboard-list"></i></span><div><h1>Fiches produits</h1><p>Renseignez les informations commerciales et caractéristiques techniques publiques.</p></div></div></div><?php if(isset($_GET['saved'])):?><div class="alert alert-success">La fiche produit a été enregistrée.</div><?php endif;?><?php if(isset($error)):?><div class="alert alert-danger"><?=pfh($error)?></div><?php endif;?><section class="sheet-card sheet-selector"><form method="get"><label class="form-label">Produit à renseigner</label><select name="id" required data-smart-select data-placeholder="Rechercher un produit…"><option value="">Sélectionner</option><?php foreach($products as$p):?><option value="<?=$p['id_produit']?>" <?=$productId===$p['id_produit']?'selected':''?>><?=pfh($p['designation'])?></option><?php endforeach?></select><button class="btn btn-primary mt-3"><i class="fa-solid fa-arrow-right"></i> Ouvrir la fiche</button></form></section><?php if($selected):?><form class="sheet-card" method="post"><input type="hidden" name="csrf_token" value="<?=pfh($_SESSION['product_sheet_csrf'])?>"><input type="hidden" name="produit_id" value="<?=$productId?>"><h2 class="h4 mb-4"><?=pfh($selected['designation'])?></h2><div class="row"><div class="col-md-6"><label class="form-label">Catégorie</label><input class="form-control" name="categorie" value="<?=pfh($selected['categorie']??'')?>" placeholder="Ex. Protection individuelle"></div><div class="col-md-6"><label class="form-label">Marque</label><input class="form-control" name="marque" value="<?=pfh($selected['marque']??'')?>"></div><div class="col-md-6"><label class="form-label">Référence fabricant</label><input class="form-control" name="reference_fabricant" value="<?=pfh($selected['reference_fabricant']??'')?>"></div><div class="col-md-6"><label class="form-label">Pays d’origine</label><input class="form-control" name="pays_origine" value="<?=pfh($selected['pays_origine']??'')?>"></div><div class="col-md-6"><label class="form-label">Garantie</label><input class="form-control" name="garantie" value="<?=pfh($selected['garantie']??'')?>" placeholder="Ex. 12 mois"></div><div class="col-md-6"><label class="form-label">Délai de livraison</label><input class="form-control" name="delai_livraison" value="<?=pfh($selected['delai_livraison']??'')?>"></div><div class="col-12"><label class="form-label">Résumé commercial</label><textarea class="form-control" name="description_courte" rows="2"><?=pfh($selected['description_courte']??'')?></textarea></div><div class="col-12"><label class="form-label">Description détaillée</label><textarea class="form-control" name="description_longue" rows="5"><?=pfh($selected['description_longue']??'')?></textarea></div></div><h3 class="h5 mt-3">Caractéristiques techniques</h3><div id="specRows"><?php foreach($specs as$spec):?><div class="spec-row"><input class="form-control" name="spec_label[]" value="<?=pfh($spec['libelle'])?>" placeholder="Caractéristique"><input class="form-control" name="spec_value[]" value="<?=pfh($spec['valeur'])?>" placeholder="Valeur"><button class="btn btn-light remove-spec" type="button"><i class="fa-solid fa-xmark"></i></button></div><?php endforeach?></div><div class="sheet-actions mt-3"><button class="btn btn-outline-primary" id="addSpec" type="button"><i class="fa-solid fa-plus"></i> Ajouter une caractéristique</button><button class="btn btn-primary" type="submit"><i class="fa-solid fa-floppy-disk"></i> Enregistrer la fiche</button><a class="btn btn-light" target="_blank" href="produit.php?id=<?=$productId?>"><i class="fa-regular fa-eye"></i> Voir la page publique</a></div></form><?php endif?></main><script src="js/smart-select.js"></script><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/js/bootstrap.bundle.min.js"></script><script>const rows=document.getElementById('specRows');function bind(){document.querySelectorAll('.remove-spec').forEach(b=>b.onclick=()=>b.closest('.spec-row').remove())}document.getElementById('addSpec')?.addEventListener('click',()=>{rows.insertAdjacentHTML('beforeend','<div class="spec-row"><input class="form-control" name="spec_label[]" placeholder="Caractéristique"><input class="form-control" name="spec_value[]" placeholder="Valeur"><button class="btn btn-light remove-spec" type="button"><i class="fa-solid fa-xmark"></i></button></div>');bind()});bind();</script></body></html>
